package edu.hoteluq.singleton;

import edu.hoteluq.service.*;
import edu.hoteluq.report.*;
import edu.hoteluq.loyalty.*;
import edu.hoteluq.exceptions.*;
import edu.hoteluq.model.BookingRecords.BookingView;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import java.time.*;
import java.math.BigDecimal;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class ReportIntegrationTest extends Phase2Fixture {
  private ReportService reports;
  private ReservationService bookings;
  @TempDir Path temp;
  private LocalDate today(){return clock.instant().atZone(edu.hoteluq.config.HotelTime.ZONE).toLocalDate();}
  private ReportQuery query(ReportQuery.Kind kind){return new ReportQuery(kind,today(),today());}
  @BeforeEach void setupReports(){reports=new ReportService(hotel);bookings=new ReservationService(hotel);room(101);}
  private BookingView pending(){return bookings.create(owner,"client-1","booking",new BookingRequest(101,FROM,FROM.plusDays(2),1,List.of(),null));}
  private BookingView paid(){service.recharge(admin,"client-1",1000,"Funds");return bookings.confirm(owner,pending().id());}
  @ParameterizedTest @EnumSource(ReportQuery.Kind.class) void allEightFamiliesUseRegisteredDataAndRequireAdmin(ReportQuery.Kind kind){var r=pending();var report=reports.generate(admin,query(kind));assertEquals(clock.instant(),report.generatedAt());assertThrows(AuthorizationException.class,()->reports.generate(owner,query(kind)));assertThrows(AuthenticationException.class,()->reports.generate("invalid",query(kind)));assertEquals(r,bookings.get(owner,r.id()));}
  @Test void realPaymentsRefundsAndRechargesRemainDistinctAcrossRetries(){var p=paid();bookings.confirm(owner,p.id());bookings.cancelByHotel(admin,p.id());bookings.cancelByHotel(admin,p.id());var result=reports.generate(admin,query(ReportQuery.Kind.REVENUE));assertEquals(new BigDecimal("200"),result.total("payments"));assertEquals(new BigDecimal("200"),result.total("refunds"));assertEquals(BigDecimal.ZERO,result.total("net"));assertEquals(new BigDecimal("1000"),reports.generate(admin,query(ReportQuery.Kind.RECHARGES)).total("recharged"));assertEquals(BigDecimal.ONE,reports.generate(admin,query(ReportQuery.Kind.CANCELLATIONS)).total("hotel"));}
  @Test void historicalPricesRemainAfterCurrentAvailabilityChanges(){var serviceLine=service.createService(admin,"Histórico",new BigDecimal("25.5"),"COP");service.recharge(admin,"client-1",1000,"Funds");var r=bookings.create(owner,"client-1","service",new BookingRequest(101,FROM,FROM.plusDays(2),1,List.of(serviceLine.id()),null));bookings.confirm(owner,r.id());service.setServiceAvailable(admin,serviceLine.id(),false);var result=reports.generate(admin,query(ReportQuery.Kind.REVENUE));assertEquals(new BigDecimal("226"),result.total("payments"));assertEquals(result.total("payments"),result.total("roomRevenue").add(result.total("serviceRevenue")));var services=reports.generate(admin,query(ReportQuery.Kind.SERVICES));assertEquals(new BigDecimal("25.5"),services.total("raw"));assertEquals(result.total("serviceRevenue"),services.total("revenue"));}
  @Test void pointReportHasRealAccrualRedemptionAndRefundAdjustments(){var loyalty=new LoyaltyService(hotel);loyalty.configure(admin,new LoyaltyPolicy("FIXTURE",1,BigDecimal.ONE,1,LoyaltyPolicy.RefundTreatment.RECALCULATE_RETAINED_PAYMENT,LoyaltyPolicy.SpentTreatment.CARRY_FORWARD_DEBT,LoyaltyPolicy.RedemptionCancellation.RESTORE_ORIGINAL_EXPIRY));paid();room(102);var r=bookings.create(owner,"client-1","two",new BookingRequest(102,FROM,FROM.plusDays(2),1,List.of(),null));var b=new Benefit(UUID.randomUUID(),1,"Gift",50,Benefit.Kind.RESERVATION_DISCOUNT,new BigDecimal("20"),null);loyalty.benefit(admin,b);loyalty.redeem(owner,r.id(),r.version(),"redemption",b.id());bookings.cancelByHotel(admin,r.id());var report=reports.generate(admin,query(ReportQuery.Kind.POINTS));assertEquals(new BigDecimal("380"),report.total("earned"));assertEquals(new BigDecimal("50"),report.total("redeemed"));assertEquals(new BigDecimal("180"),report.total("revoked"));assertEquals(new BigDecimal("50"),report.total("restored"));assertEquals(new BigDecimal("200"),report.total("available"));}
  @Test void reportExpiryDoesNotMutateOperationalHistory(){var loyalty=new LoyaltyService(hotel);loyalty.configure(admin,new LoyaltyPolicy("FIXTURE",1,BigDecimal.ONE,1,LoyaltyPolicy.RefundTreatment.RECALCULATE_RETAINED_PAYMENT,LoyaltyPolicy.SpentTreatment.CARRY_FORWARD_DEBT,LoyaltyPolicy.RedemptionCancellation.KEEP_SPENT));var p=paid();var before=loyalty.account(owner,"client-1");clock.advance(Duration.between(clock.instant(),PointsLedger.expiry(p.payment().at())));admin=service.login("admin@example.com",adminPassword).token();var one=reports.generate(admin,query(ReportQuery.Kind.POINTS));var two=reports.generate(admin,query(ReportQuery.Kind.POINTS));assertEquals(one,two);assertEquals(new BigDecimal("200"),one.total("expired"));var captured=hotel.withSession(admin,hotel::reportSnapshot).points().stream().filter(a->a.clientId().equals("client-1")).findFirst().orElseThrow();assertEquals(before.history(),captured.history());}
  @Test void utf8ExportIncludesMetadataRowsCriteriaAndExactTotalsWithoutSecrets() throws Exception {paid();var r=reports.generate(admin,query(ReportQuery.Kind.REVENUE));var out=reports.export(admin,r,new TxtReportExporter(),temp.resolve("ingresos.txt"),false);String text=Files.readString(out,StandardCharsets.UTF_8);assertTrue(text.contains("Ingresos por periodo"));assertTrue(text.contains("America/Bogota"));assertTrue(text.contains("Periodo inclusivo"));assertTrue(text.contains("Filtros:"));assertTrue(text.contains("200 COP"));assertTrue(text.contains("TOTALES"));assertFalse(text.contains("CARD-"));assertFalse(text.contains("ana@example.com"));assertFalse(text.contains(ownerPassword));assertFalse(text.contains(admin));assertThrows(AuthorizationException.class,()->reports.export(owner,r,new TxtReportExporter(),temp.resolve("forbidden.txt"),false));assertFalse(Files.exists(temp.resolve("forbidden.txt")));}
  @Test void exportDoesNotOverwriteWithoutExplicitConsentAndLeavesNoTempFile() throws Exception {var r=reports.generate(admin,query(ReportQuery.Kind.RECHARGES));Path target=temp.resolve("file.txt");Files.writeString(target,"old");assertThrows(FileAlreadyExistsException.class,()->reports.export(admin,r,new TxtReportExporter(),target,false));assertEquals("old",Files.readString(target));try(var files=Files.list(temp)){assertEquals(1,files.count());}reports.export(admin,r,new TxtReportExporter(),target,true);assertTrue(Files.readString(target).contains("Recargas"));}
  @Test void exportingDisplayedSnapshotDoesNotSilentlyRecalculateAfterNewMovements() throws Exception {var r=reports.generate(admin,query(ReportQuery.Kind.RECHARGES));service.recharge(admin,"client-1",1000,"Later");var bytes=reports.render(admin,r,new TxtReportExporter());assertTrue(new String(bytes,StandardCharsets.UTF_8).contains("Total recargado (no ingreso): 0 COP"));assertEquals(new BigDecimal("1000"),reports.generate(admin,query(ReportQuery.Kind.RECHARGES)).total("recharged"));}
  @Test void concurrentReadCannotObserveDebitWithoutPayment() throws Exception {
    service.recharge(admin,"client-1",1000,"Funds");var r=pending();CountDownLatch debit=new CountDownLatch(1),release=new CountDownLatch(1),readerStarted=new CountDownLatch(1);
    hotel.transactionProbe=stage->{if(stage==Hotel.Stage.AFTER_TRANSFER){debit.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new HotelException("Timeout");}catch(InterruptedException ex){throw new HotelException("Interrupted");}}};
    try(var executor=Executors.newFixedThreadPool(2)){
      var payment=executor.submit(()->bookings.confirm(owner,r.id()));assertTrue(debit.await(5,TimeUnit.SECONDS));var read=executor.submit(()->{readerStarted.countDown();return reports.generate(admin,query(ReportQuery.Kind.REVENUE));});assertTrue(readerStarted.await(5,TimeUnit.SECONDS));assertFalse(read.isDone());release.countDown();payment.get(5,TimeUnit.SECONDS);assertEquals(new BigDecimal("200"),read.get(5,TimeUnit.SECONDS).total("payments"));
    }finally{release.countDown();hotel.transactionProbe=stage->{};}
  }
  @Test void laterRefundIsNegativeCashFlowWithoutRecapturingOriginalIncome(){var p=paid();clock.advance(Duration.ofDays(1));admin=service.login("admin@example.com",adminPassword).token();bookings.cancelByHotel(admin,p.id());var result=reports.generate(admin,query(ReportQuery.Kind.REVENUE));assertEquals(BigDecimal.ZERO,result.total("payments"));assertEquals(new BigDecimal("200"),result.total("refunds"));assertEquals(new BigDecimal("-200"),result.total("net"));}
  @Test void rolledBackPaymentCannotBecomeReportIncome(){service.recharge(admin,"client-1",1000,"Funds");var p=pending();hotel.transactionProbe=stage->{if(stage==Hotel.Stage.AFTER_RECEIPT)throw new HotelException("Failure");};assertThrows(HotelException.class,()->bookings.confirm(owner,p.id()));hotel.transactionProbe=stage->{};assertEquals(BigDecimal.ZERO,reports.generate(admin,query(ReportQuery.Kind.REVENUE)).total("payments"));}
  @Test void customerCannotNavigateToReportsOrExportAnOldResultAfterLogout() throws Exception {var desktop=new edu.hoteluq.ui.DesktopController(hotel);desktop.login("ana@example.com",ownerPassword);assertFalse(desktop.navigation().contains(edu.hoteluq.ui.DesktopController.Screen.REPORTS));assertThrows(AuthorizationException.class,()->desktop.navigate(edu.hoteluq.ui.DesktopController.Screen.REPORTS));var result=reports.generate(admin,query(ReportQuery.Kind.RECHARGES));service.logout(admin);assertThrows(AuthenticationException.class,()->reports.export(admin,result,new TxtReportExporter(),temp.resolve("after-logout.txt"),false));assertFalse(Files.exists(temp.resolve("after-logout.txt")));}

}
